1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
11	
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumBy = <T>(items: T[], amount: (item: T) => number): number =>
18	  items.reduce((sum, item) => sum + amount(item), 0);
19	
20	const sumOfItemPrices = (items: Item[]): number =>
21	  sumBy(items, (item) => priceList[item.type]);
22	
23	const countOf = (type: string, items: Item[]): number =>
24	  items.filter((item) => item.type === type).length;
25	
26	const componentPremium = (type: string, items: Item[]): number => {
27	  const count = countOf(type, items);
28	  return count === COMPONENT_BLOCK_SIZE
29	    ? COMPONENT_BLOCK_PRICE
30	    : count * priceList[type];
31	};
32	
33	export const basePremium = (items: Item[]): number => {
34	  const nonComponents = items.filter(
35	    (item) => !COMPONENT_TYPES.includes(item.type),
36	  );
37	  const componentsTotal = COMPONENT_TYPES.reduce(
38	    (total, type) => total + componentPremium(type, items),
39	    0,
40	  );
41	  return sumOfItemPrices(nonComponents) + componentsTotal;
42	};
43	
44	const PROCESSING_FEE = 5;
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const FIRST_INSURANCE_RATE = 0.1;
49	const LOYALTY_DISCOUNT_RATE = 0.2;
50	const LOYALTY_THRESHOLD_YEARS = 2;
51	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
52	
53	type Customer = { yearsWithMHPCO: number };
54	
55	const itemBasePremium = (item: Item): number => basePremium([item]);
56	
57	const hasEnchantmentAtLeast = (item: Item, threshold: number): boolean =>
58	  (item.enchantment ?? 0) >= threshold;
59	
60	// A surcharge is a fraction of the item's own base premium, charged only when
61	// the item satisfies the given predicate.
62	const surchargeWhen =
63	  (qualifies: (item: Item) => boolean, rate: number) =>
64	  (item: Item): number =>
65	    qualifies(item) ? itemBasePremium(item) * rate : 0;
66	
67	const isCursed = (item: Item): boolean => item.cursed ?? false;
68	
69	const isHighEnchantment = (item: Item): boolean =>
70	  hasEnchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
71	
72	const curseSurchargeFor = surchargeWhen(isCursed, CURSE_SURCHARGE_RATE);
73	
74	const enchantSurchargeFor = surchargeWhen(
75	  isHighEnchantment,
76	  HIGH_ENCHANTMENT_RATE,
77	);
78	
79	const surchargesFor = (item: Item): number =>
80	  curseSurchargeFor(item) + enchantSurchargeFor(item);
81	
82	// Premiums round in MHPCO's favor — up. (Claim payouts round down, also in MHPCO's favor.)
83	const roundInFavorUp = (amount: number): number => Math.ceil(amount);
84	
85	// Claim payouts round in MHPCO's favor — down.
86	const roundInFavorDown = (amount: number): number => Math.floor(amount);
87	
88	const quotePremium = (
89	  items: Item[],
90	  customer: Customer,
91	  isFollowUp: boolean,
92	): number => {
93	  const policyBase = basePremium(items);
94	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
95	  const loyaltyDiscount =
96	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
97	      ? policyBase * LOYALTY_DISCOUNT_RATE
98	      : 0;
99	  const followUpDiscount = isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
100	  const policyCharges =
101	    policyBase + firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
102	
103	  const itemSurcharges = sumBy(items, surchargesFor);
104	
105	  return roundInFavorUp(policyCharges + itemSurcharges + PROCESSING_FEE);
106	};
107	
108	const insuranceValueList: Record<string, number> = {
109	  sword: 1000,
110	  amulet: 600,
111	  staff: 800,
112	  potion: 400,
113	  rune: 250,
114	  moonstone: 250,
115	};
116	
117	const CAP_MULTIPLIER = 2;
118	const DEDUCTIBLE = 100;
119	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
120	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
121	
122	const insuranceSum = (items: Item[]): number =>
123	  sumBy(items, (item) => insuranceValueList[item.type]);
124	
125	// The cap is derived from the unmodified insurance value, independent of premium modifiers.
126	const initialCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
127	
128	type Damage = { itemType: string; amount: number };
129	
130	const isHighlyEnchanted = (item: Item): boolean =>
131	  hasEnchantmentAtLeast(item, HIGH_ENCHANTMENT_PAYOUT_THRESHOLD);
132	
133	const coveredAmountFor = (damage: Damage, insuredItem: Item): number =>
134	  isHighlyEnchanted(insuredItem)
135	    ? damage.amount * HIGH_ENCHANTMENT_PAYOUT_RATE
136	    : damage.amount;
137	
138	// Validates a damage against the policy and returns the insured item it refers
139	// to. Throws if the amount is negative or the item is not in the policy.
140	const validatedInsuredItem = (damage: Damage, items: Item[]): Item => {
141	  if (damage.amount < 0) {
142	    throw new Error(`Invalid damage amount: ${damage.amount}`);
143	  }
144	  const insuredItem = items.find((item) => item.type === damage.itemType);
145	  if (insuredItem === undefined) {
146	    throw new Error(`Damaged item not in policy: ${damage.itemType}`);
147	  }
148	  return insuredItem;
149	};
150	
151	const reimbursementFor = (damage: Damage, items: Item[]): number => {
152	  const insuredItem = validatedInsuredItem(damage, items);
153	  return coveredAmountFor(damage, insuredItem) - DEDUCTIBLE;
154	};
155	
156	type Incident = { cause: string; damages: Damage[] };
157	
158	type QuoteStep = { op: "quote"; items: Item[] };
159	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
160	type Step = QuoteStep | ClaimStep;
161	type Scenario = { customer: Customer; steps: Step[] };
162	
163	type Policy = { items: Item[]; remainingCap: number };
164	type QuoteResult = { premium: number };
165	type ClaimResult = { payout: number; remainingCap: number };
166	type StepResult = QuoteResult | ClaimResult;
167	
168	const isKnownType = (type: string): boolean => type in priceList;
169	
170	const assertKnownTypes = (items: Item[]): void => {
171	  const unknownItem = items.find((item) => !isKnownType(item.type));
172	  if (unknownItem !== undefined) {
173	    throw new Error(`Unknown item type: ${unknownItem.type}`);
174	  }
175	};
176	
177	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
178	  const policies: Record<number, Policy> = {};
179	  let quoteCount = 0;
180	
181	  const handleQuote = (step: QuoteStep, index: number): QuoteResult => {
182	    assertKnownTypes(step.items);
183	    const isFollowUp = quoteCount > 0;
184	    quoteCount += 1;
185	    policies[index] = {
186	      items: step.items,
187	      remainingCap: initialCap(step.items),
188	    };
189	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
190	  };
191	
192	  const handleClaim = (step: ClaimStep): ClaimResult => {
193	    const policy = policies[step.policy];
194	    const damages = step.incident.damages;
195	    for (const damage of damages) {
196	      const damageCount = damages.filter(
197	        (other) => other.itemType === damage.itemType,
198	      ).length;
199	      const insuredCount = countOf(damage.itemType, policy.items);
200	      if (damageCount > insuredCount) {
201	        throw new Error(`Too many damages for item type: ${damage.itemType}`);
202	      }
203	    }
204	    const desiredPayout = roundInFavorDown(
205	      sumBy(damages, (damage) => reimbursementFor(damage, policy.items)),
206	    );
207	    const payout = Math.min(desiredPayout, policy.remainingCap);
208	    const remainingCap = policy.remainingCap - payout;
209	    policy.remainingCap = remainingCap;
210	    return { payout, remainingCap };
211	  };
212	
213	  const results = scenario.steps.map((step, index): StepResult =>
214	    step.op === "quote" ? handleQuote(step, index) : handleClaim(step),
215	  );
216	
217	  return { results };
218	};
